function executionFields(
	error: Error | string,
): Omit<CliDiagnostic, "code" | "message"> {
	if (!isHevyHttpError(error) && !isTaggedClientError(error)) return {};
	const {
		code: _code,
		status: _status,
		...execution
	} = createExecutionErrorProjection(error);
	return execution;
}

